import os,re,collections
root='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'
def modname(p):
    rel=os.path.relpath(p,root)
    return rel[:-5].replace('/','.')
files={}
for dp,dn,fn in os.walk(root):
    if '.lake' in dp: continue
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); files[modname(p)]=p
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)')
deps={}
for m,p in files.items():
    ds=[]
    for line in open(p,errors='replace'):
        mm=imp.match(line)
        if mm: ds.append(mm.group(1))
        elif line.strip() and not line.startswith('/-') and not line.startswith('--') and 'import' not in line:
            pass
    deps[m]=[d for d in ds if d in files]
seen=set()
stack=['AlgebraicJacobian']
while stack:
    m=stack.pop()
    if m in seen or m not in files: continue
    seen.add(m); stack.extend(deps[m])
unrooted=sorted(set(files)-seen)
print('total modules',len(files),'rooted',len(seen),'unrooted',len(unrooted))
open('/tmp/unrooted.txt','w').write('\n'.join(unrooted))
open('/tmp/rooted.txt','w').write('\n'.join(sorted(seen)))
for u in unrooted: print('  UNROOTED',u)
EOF
